import{z as B,x as o,o as r,c as n,q as t,j as i,D as l,d as e,s,S as h,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"GQA 与 MQA 的内核差异","description":"","frontmatter":{"title":"GQA 与 MQA 的内核差异","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-gqa-mqa-kernels.md","filePath":"llm/ak-gqa-mqa-kernels.md","lastUpdated":1791063341000}'),m={name:"llm/ak-gqa-mqa-kernels.md"};function _(d,a,p,q,k,c){const A=o("Mermaid");return r(),n("div",null,[a[2]||(a[2]=t('<h1 id="gqa-与-mqa-的内核差异" tabindex="-1">GQA 与 MQA 的内核差异 <a class="header-anchor" href="#gqa-与-mqa-的内核差异" aria-label="Permalink to &quot;GQA 与 MQA 的内核差异&quot;">​</a></h1><div class="epigraph"><p>少几套 KV 头省下的字节，要靠内核里真正被复用才兑现；结构省了、内核照旧，账就落空。</p><footer>—— 据 Shazeer, 2019；Ainslie et al., 2023 整理</footer></div><p><a href="/llm/ak-smem-register-budget">上一课</a>把片上预算钉住，基础机制三课收束。本课进入变体的内核单元，第一个变体动的是头这一维。<a href="/llm/gqa">GQA</a> 与 <a href="/llm/mqa">MQA</a> 在结构课里定过 \\(h_{kv}\\) 的谱系：\\(h_{kv}=h_q\\) 即 MHA，\\(h_{kv}=1\\) 即 MQA，中间是分组共享。本课只站在内核这一侧问：\\(h_q\\) 个查询头共享 \\(h_{kv}\\) 套键值，这层共享在核内怎么落地，才把省下的字节真的兑成时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结构把 KV 字节除以 \\(h_q/h_{kv}\\)，那是缓存容量的账；带宽的账要内核来结。若每查询头仍按 MHA 代码独立去读「自己的」K 和 V，同一段 KV 就要从 HBM 被搬 \\(h_q/h_{kv}\\) 遍，带宽一分未省；若在模型层把 KV 沿头维展开成 \\(h_q\\) 份再喂旧内核，容量与带宽双双回到原点，还多占了显存。共享必须在加载路径上发生一次、被用足 \\(h_q/h_{kv}\\) 次，账才算平。</p><p><span class="marginnote">术语翻译：\\(h_q\\) 是查询头的个数，\\(h_{kv}\\) 是键值头的个数，\\(h_q/h_{kv}\\) 就是「几个查询头共用一套键值」，也叫组大小。Llama-2-70B 是 64 个查询头配 8 套键值——每组 8 个查询头，排队用同一份 K、V。</span></p><h3 id="共享发生在哪一层" tabindex="-1">共享发生在哪一层 <a class="header-anchor" href="#共享发生在哪一层" aria-label="Permalink to &quot;共享发生在哪一层&quot;">​</a></h3><p>候选层级有三个：HBM 之后、L2 之中、SRAM 之内。L2 是芯片级共享，多个块读同一段 KV 有机会命中，但调度不保证同时驻留，复用是概率性的；SRAM 里的复用是确定性的——载一次、用足，这恰好是上一课预算表腾出来的地方。</p>',8)),(r(),i(h,null,{default:l(()=>[s(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E5%B1%95%E5%BC%80%E6%88%90%20h_q%20%E4%BB%BD%E5%96%82%E6%97%A7%E5%86%85%E6%A0%B8%22%5D%20--%3E%20X1%5B%22%E5%AE%B9%E9%87%8F%E4%B8%8E%E5%B8%A6%E5%AE%BD%E5%8F%8C%E5%8F%8C%E5%9B%9E%E5%88%B0%E5%8E%9F%E7%82%B9%22%5D%0A%20%20B%5B%22%E6%8C%87%E6%9C%9B%20L2%20%E6%92%9E%E4%B8%8A%E7%BC%93%E5%AD%98%22%5D%20--%3E%20X2%5B%22%E8%B0%83%E5%BA%A6%E4%B8%8D%E4%BF%9D%E8%AF%81%E9%A9%BB%E7%95%99%3A%20%E6%A6%82%E7%8E%87%E6%80%A7%E5%A4%8D%E7%94%A8%22%5D%0A%20%20C%5B%22%E8%BD%BD%E5%85%A5%20SRAM%20%E4%B8%80%E6%AC%A1%2C%20%E7%BB%84%E5%86%85%E5%BE%AA%E7%8E%AF%E7%94%A8%E8%B6%B3%22%5D%20--%3E%20X3%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%E5%A4%8D%E7%94%A8%2C%20%E5%B8%A6%E5%AE%BD%E8%B4%A6%E7%BB%93%E5%B9%B3%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"方法",tabindex:"-1"},[e("方法 "),E("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("内核侧两个动作。第一，头映射：网格按查询头展开，第 \\(i\\) 个查询头对应 KV 组 \\(g=\\lfloor i/(h_q/h_{kv})\\rfloor\\)；载入第 \\(g\\) 套 K、V 进 smem 一次，组内 \\(h_q/h_{kv}\\) 个查询头循环复用，输出各写各的。第二，解码的极端情形：\\(h_{kv}=1\\) 时整套 KV 与批内所有请求、所有头共享，加载可以沿批与头合并，跨请求共享前缀还能级联成一段公共读加各请求的私有读，见 "),E("a",{href:"/llm/flashinfer"},"FlashInfer 内核库"),e("的级联口径。前填侧的账不同：FLOPs 仍按 \\(h_q\\) 算，几乎不减，省在写出 KV 与缓存容量上。")],-1)),(r(),i(h,null,{default:l(()=>[s(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22Q%20%E5%A4%B4%20i%20%E8%BF%9B%E5%9D%97%22%5D%20--%3E%20G%5B%22%E6%9F%A5%E7%BB%84%EF%BC%9Ag%20%3D%20i%20%C3%B7%20(h_q%20%2F%20h_kv)%22%5D%0A%20%20G%20--%3E%20L%5B%22%E7%AC%AC%20g%20%E5%A5%97%20K%2CV%20%E8%BD%BD%E5%85%A5%20smem%20%E4%B8%80%E6%AC%A1%22%5D%0A%20%20L%20--%3E%20C%5B%22%E7%BB%84%E5%86%85%20h_q%2Fh_kv%20%E4%B8%AA%E6%9F%A5%E8%AF%A2%E5%A4%B4%E5%BE%AA%E7%8E%AF%E5%A4%8D%E7%94%A8%22%5D%0A%20%20C%20--%3E%20W%5B%22%E5%90%84%E5%A4%B4%E5%86%99%E8%BE%93%E5%87%BA%EF%BC%9B%E4%B8%8B%E4%B8%80%E7%BB%84%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么这个循环买得起带宽账：解码一步的 KV 读量从 \\(h_q\\) 套降到 \\(h_{kv}\\) 套，每字节被组内循环用足；KV 读正是<a href="/llm/arithmetic-intensity-decode">解码的算术强度</a>里压垮小 batch 的那本账，把它除以 8，decode 的每步时间近似也除以 8。组内循环的代价是 smem 里多驻一份 K、V——上一课的双缓冲与 tile 权衡在这里直接接上：\\(d\\) 与 \\(B_c\\) 不变，份额够了，占用率不掉。</p><p><span class="marginnote">数字实例：batch=32 的解码步，MHA（\\(h_q=64\\)）每步要读 \\(32\\times64\\) 套 KV，GQA（\\(h_{kv}=8\\)）只读 \\(32\\times8\\) 套——读量正好除以 8。解码是「读得多、算得少」的活，小 batch 下读量砍八倍，每步时间就近似快八倍。</span></p><p>错法有两种，都在生产代码里常见。其一，内核不支持组映射，于是给每个 KV 组起一个独立内核调用、组内头串行：共享退化为时间上的先后读，HBM 字节数回到 MHA。其二，用张量展开假装共享：<code>expand</code> 出 \\(h_q\\) 份视图再广播——若下游内核按视图具象化，显存与带宽立刻翻回；视图必须活到加载指令那一层才作数。</p><p><span class="marginnote">初学者容易以为「<code>expand</code> 一下就算共享了」——它只是造出一张「看起来有 64 份」的账面视图，内存里仍是那一份。可只要下游内核真按 64 份去读，或实现把视图物化成真拷贝，省下的字节就全赔回去。共享要落在加载指令那一层才算数。</span></p><p><span class="marginnote">Llama-2-70B 取 \\(h_q=64\\)、\\(h_{kv}=8\\)：解码每步 KV 字节相对 MHA 除以 8。这笔账是内核里那段组内循环买来的，不是结构自己买来的——同样的权重，配一个不识组的内核，一分钱都省不下。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>组内是硬共享，池化加短训转 GQA 的质量代价与 \\(h_{kv}\\) 的甜点选择是结构课的题目；<a href="/llm/ainslie-gqa">GQA 论文</a>与 <a href="/llm/shazeer-mqa">MQA 论文</a>的口径本课不重复。张量并行要求 \\(h_{kv}\\) 可被切分整除，那是分片布局问题，落点在并行课程。跨请求共享 KV 的地址问题——页表与引用计数——是下一课的主题：本课的共享发生在头之间，下一课发生在请求之间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构省的是 KV 字节与容量，带宽的账由内核的组映射与 smem 复用来结。</li><li>头映射 \\(g=\\lfloor i/(h_q/h_{kv})\\rfloor\\)：K、V 按组载入一次，组内循环用足。</li><li>MQA 的 \\(h_{kv}=1\\) 把共享推到批与请求级，解锁级联与合并加载。</li><li>展开视图不等于共享：必须活到加载路径，否则显存带宽双双翻回。</li><li>前填侧几乎不省 FLOPs，省的是 KV 写出与缓存。</li><li>出处：Shazeer, <em>Fast Transformer Decoding</em>, 2019；Ainslie et al., <em>GQA</em>, 2023。</li></ul>',10))])}const V=B(m,[["render",_]]);export{D as __pageData,V as default};
